/usr/bin/zsh -lc "python3 -c 'import os,hashlib,json; p=os.path.realpath(\"index.ts\"); h=lambda:hashlib.sha256(open(p,\"rb\").read()).hexdigest(); before=h(); result={\"path\":p,\"sha256_before\":before};
try:
 fd=os.open(p,os.O_WRONLY); os.close(fd); result[\"open\"]=\"SUCCEEDED\"
except OSError as e:
 result.update(open=\"DENIED\",errno=e.errno,error=str(e))
mounts=[]
for line in open(\"/proc/self/mountinfo\"):
 parts=line.split(); mount=parts[4].replace(\"\\\\040\",\" \");
 if p==mount or p.startswith(mount.rstrip(\"/\")+\"/\"): mounts.append((len(mount),line.strip()))
result[\"covering_mounts\"]=[v for _,v in sorted(mounts)]; result[\"sha256_after\"]=h(); result[\"unchanged\"]=before==result[\"sha256_after\"]; print(json.dumps(result))'"

